func (s pageDocHandlers) GET(w http.ResponseWriter, r *http.Request) {

	var path datapages.Path[struct {
		ID string `path:"id"`
	}]
	path.Values.ID = r.PathValue("id")

	instanceID, err := newStateInstanceID()
	if err != nil {
		s.httpErrIntern(w, r, nil, "minting state instance", err)
		return
	}
	w.Header().Set(stateInstanceIDHeader, instanceID)
	// A shared cache would expose this bearer id to another visitor.
	w.Header().Set("Cache-Control", "no-store")

	p := dpapp.PageDoc{
		App: s.app,
	}
	defer s.recoverPanic(w, r, nil, "PageDoc.GET")
	body, head, enableBackgroundStreaming, err := p.GET(r, path)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling PageDoc.GET", err)
		return
	}
	genericHead := s.app.Head(r)

	bodyAttrs := func(w http.ResponseWriter) {
		if !enableBackgroundStreaming {
			httpserve.WriteReloadOnVisibility(w)
		}
	}

	bodySuffix := func(w http.ResponseWriter) {

		_, _ = io.WriteString(w, ` data-init="@get('`)
		_, _ = io.WriteString(w, `/doc/`)
		htmlattr.WritePathValue(w, path.Values.ID)
		_, _ = io.WriteString(w, `/`)
		_, _ = io.WriteString(w, `_$/'`)
		if enableBackgroundStreaming {
			_, _ = io.WriteString(w, `,{openWhenHidden:true,retry:'always',retryMaxCount:Infinity})"`)
		} else {
			_, _ = io.WriteString(w, `,{retry:'always',retryMaxCount:Infinity})"`)
		}
	}

	if err := s.writeHTML(
		w, r, http.StatusOK, genericHead, head, body, bodyAttrs, bodySuffix,
	); err != nil {
		s.LogErr("rendering PageDoc", err)
		return
	}
}

