type pageError404Handlers struct{ *Server }

func (s pageError404Handlers) GET(w http.ResponseWriter, r *http.Request) {
	p := dpapp.PageError404{
		App: s.app,
	}
	defer s.recoverPanic(w, r, nil, "PageError404.GET")
	body, head, err := p.GET(r)
	if err != nil {
		s.httpErr404(w, r, "handling PageError404.GET", err)
		return
	}
	genericHead := s.app.Head(r)

	if err := s.writeHTML(
		w, r, http.StatusOK, genericHead, head, body, nil, nil,
	); err != nil {
		s.LogErr("rendering PageError404", err)
		return
	}
}

type pageIndexHandlers struct{ *Server }

func (s pageIndexHandlers) GET(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" {
		s.render404(w, r)
		return
	}

	p := dpapp.PageIndex{
		App: s.app,
	}
	defer s.recoverPanic(w, r, nil, "PageIndex.GET")
	body, head, err := p.GET(r)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling PageIndex.GET", err)
		return
	}
	genericHead := s.app.Head(r)

	bodyAttrs := func(w http.ResponseWriter) {
		httpserve.WriteReloadOnVisibility(w)
	}

	bodySuffix := func(w http.ResponseWriter) {

		_, _ = io.WriteString(w, ` data-init="@get('/_$/',{retry:'always',retryMaxCount:Infinity})"`)
	}

	if err := s.writeHTML(
		w, r, http.StatusOK, genericHead, head, body, bodyAttrs, bodySuffix,
	); err != nil {
		s.LogErr("rendering PageIndex", err)
		return
	}
}

func (s pageIndexHandlers) GETStream(w http.ResponseWriter, r *http.Request) {
	if !s.CheckDatastarRequest(w, r) {
		return
	}

	p := dpapp.PageIndex{
		App: s.app,
	}
	s.handleStreamRequest(w, r, evSubjPageIndex,
		nil,
		nil,
		func(
			streamID datapages.StreamID,
			sse *dpsse.Stream, ch <-chan messaging.Message,
		) {
			defer s.recoverPanic(w, r, sse, "PageIndex stream")
			var eventListChanged dpapp.EventListChanged
			for msg := range ch {
				switch msg.Subject {
				case EvSubjListChanged:
					eventListChanged = dpapp.EventListChanged{}
					if err := json.Unmarshal(msg.Data, &eventListChanged); err != nil {
						s.LogErr("unmarshaling EventListChanged JSON", err)
						continue
					}
					if err := p.OnListChanged(
						eventListChanged,
						sse,
					); err != nil {
						s.LogErr("handling PageIndex.OnListChanged", err)
					}
				}
			}
		})
}

