type dispatcherEventDocChanged struct {
	s   *Server
	ctx context.Context
}

func (d dispatcherEventDocChanged) Dispatch(e dpapp.EventDocChanged) error {
	return d.DispatchCtx(d.ctx, e)
}

func (d dispatcherEventDocChanged) DispatchCtx(
	ctx context.Context, e dpapp.EventDocChanged,
) error {
	if e.Doc == "" {
		return errors.New("EventDocChanged.Doc must not be empty")
	}
	j, err := json.Marshal(e)
	if err != nil {
		return fmt.Errorf("marshaling EventDocChanged JSON: %w", err)
	}
	subj := "doc.changed." + subject.Encode(string(e.Doc))
	err = d.s.messageBroker.Publish(ctx, d.s.messageBrokerMetrics, subj, j)
	if err != nil {
		return fmt.Errorf("publishing subject %q: %w", subj, err)
	}
	return nil
}

type dispatcherEventListChanged struct {
	s   *Server
	ctx context.Context
}

func (d dispatcherEventListChanged) Dispatch(e dpapp.EventListChanged) error {
	return d.DispatchCtx(d.ctx, e)
}

func (d dispatcherEventListChanged) DispatchCtx(
	ctx context.Context, e dpapp.EventListChanged,
) error {
	j, err := json.Marshal(e)
	if err != nil {
		return fmt.Errorf("marshaling EventListChanged JSON: %w", err)
	}
	err = d.s.messageBroker.Publish(ctx, d.s.messageBrokerMetrics, EvSubjListChanged, j)
	if err != nil {
		return fmt.Errorf("publishing subject %q: %w", EvSubjListChanged, err)
	}
	return nil
}
